class Solution {
    int gcd(int a, int b) {
        while (b) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
public:
    int subarrayGCD(vector<int>& nums, int k) {
        int ans = 0;
        unordered_map<int, int> prev;
        for (int x : nums) {
            unordered_map<int, int> curr;
            curr[x] = 1;
            for (auto& [g, cnt] : prev) {
                curr[gcd(g, x)] += cnt;
            }
            if (curr.count(k)) ans += curr[k];
            prev = move(curr);
        }
        return ans;
    }
};
